window.TC_HELP=[{"slug":"join-the-talent-network","title":"How do I join the talent network?","cat":"pro","summary":"Joining is free and takes about five minutes. A recruiter reaches out the same day.","kw":"join sign up signup register apply application network free cost onboard start new"},{"slug":"pick-up-shifts","title":"How do I find and pick up shifts?","cat":"pro","summary":"Browse open shifts by role and location on the job board or in the app, then claim one with a tap.","kw":"find shift shifts pick claim jobs job board open work near me schedule available browse"},{"slug":"change-or-cancel-a-shift","title":"How do I change or cancel a shift?","cat":"pro","summary":"Contact your recruiter as early as you can. Text is fastest, and they’ll update the practice for you.","kw":"change cancel cancellation swap reschedule shift sick late running late cant make it emergency drop"},{"slug":"pay-and-timesheets","title":"When and how do I get paid?","cat":"pro","summary":"Talencia professionals are W-2 employees paid through Talencia payroll. Pay questions go to a person who can see your file.","kw":"pay paid paycheck payday payroll timesheet hours direct deposit wages money pay card missing"},{"slug":"benefits","title":"What benefits do I get?","cat":"pro","summary":"Full-time professionals get medical, dental, vision and 401(k). Workers’ comp is included for all W-2 professionals.","kw":"benefits insurance health medical dental vision 401k 401(k) retirement workers comp full-time coverage"},{"slug":"talencia-rewards","title":"How do Talencia Rewards work?","cat":"pro","summary":"Every hour you work earns cash back. Same-day pay to your Talencia pay card is coming soon.","kw":"rewards reward points cash back bonus earn same day pay pay card perks"},{"slug":"keep-credentials-current","title":"How do I keep my credentials up to date?","cat":"pro","summary":"Keep your license, certifications and CPR current in the app so you can say yes to short-notice shifts.","kw":"credentials license licence renew renewal expire expiring cpr certification certificate upload documents"},{"slug":"request-talent","title":"How do I request a professional?","cat":"prac","summary":"Tell us the role, date and office. A recruiter reaches out the same day; medical facilities get coverage within 24 hours.","kw":"request staff hire need coverage cover fill shift fast quick quickly urgent 24 hours same day temp short staffed order book professional hygienist assistant"},{"slug":"how-candidates-are-vetted","title":"How are professionals vetted?","cat":"prac","summary":"AI screening plus face-to-face interviews, license and credential checks, background checks and references.","kw":"vetted vetting screening screen background check references interview quality license verified trust"},{"slug":"who-employs-the-professional","title":"Who employs the professionals you send?","cat":"prac","summary":"Talencia by KAD does. Every professional is a W-2 employee, so payroll, taxes, workers’ comp and compliance sit with us.","kw":"employ employer w-2 w2 payroll taxes liability workers comp compliance who pays insurance"},{"slug":"temp-to-hire","title":"Can a temporary professional become a permanent hire?","cat":"prac","summary":"Yes. We offer temp, temp-to-hire and permanent placement, so you can try the fit before you commit.","kw":"permanent perm temp to hire convert hire full time direct hire placement try"},{"slug":"employer-of-record","title":"What is Employer of Record?","cat":"prac","summary":"You keep your team and the lead. We become the employer on paper and take on payroll, HR and liability.","kw":"eor employer of record payroll hr liability peo outsource paperwork"},{"slug":"other-industries","title":"Do you staff outside healthcare?","cat":"prac","summary":"Yes. Talencia places professionals across all industries nationwide, including sales, HR, finance, IT and trades.","kw":"industries outside healthcare sales hr finance it trades office non medical other"},{"slug":"sign-in","title":"How do I sign in?","cat":"acct","summary":"One login covers shifts, rewards and your recruiter. Practices use the client portal.","kw":"sign in signin login log logging password username account access portal client portal locked forgot"},{"slug":"the-talencia-app","title":"What can I do in the Talencia app?","cat":"acct","summary":"Pick shifts, manage your schedule, keep credentials current and message your recruiter.","kw":"app mobile download iphone android phone application features what can"},{"slug":"talk-to-a-person","title":"How do I reach a real person?","cat":"acct","summary":"Call or text 214.522.2008, email recruiting@gotalencia.com, or use the chat. A real person, same day.","kw":"contact human person phone call text email reach recruiter support help talk speak agent hours"}];
/* keyword search: title words score 3, keywords 2, summary 1, plus 2 for each extra question word an article matches; simple stems match (cancel ~ cancelling, screen ~ screened) */
window.TC_HELP_SEARCH=(q,n)=>{const STOP=new Set('a an and are can do does for from get how i in is it me my of on or the to what when where who why with you your'.split(' '));
 const tok=s=>(s.toLowerCase().replace(/’/g,"'").match(/[a-z0-9()']+/g)||[]).filter(w=>w.length>1&&!STOP.has(w));
 const stem=w=>w.length>4?w.replace(/(ations?|ings?|ling|ed|es|s)$/,''):w;
 const hit=(w,ws)=>{const a=stem(w);return ws.some(x=>{const b=stem(x);return a===b||(a.length>=5&&b.length>=5&&Math.abs(a.length-b.length)<=2&&(a.startsWith(b)||b.startsWith(a)))})};
 const qs=tok(q);if(!qs.length)return[];
 return window.TC_HELP.map(a=>{const t=tok(a.title),k=tok(a.kw),s=tok(a.summary);let sc=0,m=0;qs.forEach(w=>{const v=(hit(w,t)?3:0)+(hit(w,k)?2:0)+(hit(w,s)?1:0);sc+=v;m+=v?1:0});return{a,sc:sc+2*Math.max(0,m-1)}})
  .filter(x=>x.sc>0).sort((x,y)=>y.sc-x.sc).slice(0,n||5)};
